-- Italian localization — additive migration
--
-- Run this manually against the production Supabase project (SQL editor or
-- `supabase db execute`). NOT applied automatically by the app or by any
-- script in this repo.
--
-- Safe by construction:
--   * Only ADDS nullable columns — never drops, renames, or recreates
--     anything. Existing rows, RLS policies, and every other column are
--     untouched.
--   * The UPDATE statements below only ever set the three new _it columns,
--     matched by existing `id` — they cannot change text/option_a/option_b,
--     category, votes, predictions, or scores.
--   * Re-running this whole file is safe/idempotent: `add column if not
--     exists` no-ops on a second run, and each `update ... where id = ...`
--     just re-applies the same Italian text.
--
-- Regenerate the UPDATE block below with:
--   npx tsx scripts/gen-italian-updates.mts

alter table questions add column if not exists text_it text;
alter table questions add column if not exists option_a_it text;
alter table questions add column if not exists option_b_it text;

